var e={"system.localMode":`Installation locale : les commandes système et les mises à jour automatiques ne sont pas disponibles ici. Consultez les instructions du dépôt.`,"profile.title":`Votre pseudo`,"profile.desc":`Utilisé quand vos messages web sont copiés sur Telegram (pas affiché sous vos messages dans les sessions).`,"profile.name":`Nom`,"profile.nameDesc":`32 caractères au plus. Vide : pas de pseudo.`,"profile.namePlaceholder":`ex. Alex`,"profile.color":`Couleur`,"profile.colorDesc":`La couleur de votre badge.`,"profile.emoji":`Emoji`,"profile.emojiDesc":`Affiché dans votre badge à la place de vos initiales (facultatif).`,"profile.preview":`Aperçu`,"profile.previewText":`Salut ! Prêt quand tu veux.`,"profile.you":`Vous`,"register.title":`Contact avec les auteurs du projet d’origine`,"register.desc":`Facultatif : les informations ci-dessous sont transmises aux auteurs du projet d’origine.`,"register.email":`E-mail (facultatif)`,"register.emailPlaceholder":`vous@exemple.com`,"register.emailDesc":`Adresse transmise aux auteurs du projet d’origine pour les alertes de sécurité et changements importants.`,"register.emailInvalid":`Ça ne ressemble pas à une adresse e-mail.`,"register.news":`M'envoyer aussi les nouveautés`,"register.newsDesc":`Les nouvelles fonctionnalités, quelques fois par mois au plus. Désinscription ici à tout moment.`,"register.count":`Aider à compter les installations (anonyme)`,"register.countDesc":`Une fois par jour : un numéro tiré au hasard, la version, le système (ex. Ubuntu 24.04, x86_64) et quelques codes de santé (service actif, Claude connecté, dernière mise à jour ratée…). Ni nom, ni e-mail, ni IP, ni nom de serveur, ni contenu.`,"register.countBlocked":`Désactivé sur ce serveur par MAXXING_NO_TELEMETRY ou DO_NOT_TRACK dans l'environnement du service.`,"register.privacy":`Envoyé à api.harness-maxxing.com. Votre pseudo et votre langue ne partent qu'avec un e-mail. Tout décocher arrête tout : nous ne contactons plus ce serveur.`,"register.statusOff":`Ce serveur ne dit rien aux auteurs.`,"register.statusOn":`Enregistré. Un signal par jour.`,"register.statusPending":`Pas encore envoyé : ce sera fait au prochain signal quotidien.`,"register.statusError":`Impossible de joindre les auteurs : {error}. Nouvel essai demain.`,"register.stop":`Arrêter, ne plus être contacté`,"license.mitTitle":`Licence MIT`,"license.mitDesc":`Le code de ce dépôt est distribué sous licence MIT. Aucune clé de licence n'est nécessaire.`,"license.thirdParty":`Les avis de copyright et les licences des composants tiers sont conservés dans le dépôt.`,"license.title":`Licence Entreprise (facultative)`,"license.desc":`harness-pilot est gratuit pour vous-même et pour une organisation qui l'utilise pour ses propres besoins. Une clé ne sert qu'aux entreprises qui en ont besoin ; elle ne change rien au fonctionnement.`,"license.read":`Lire la licence`,"license.whoTitle":`Qui a besoin d'une clé ?`,"license.who1":`Une organisation qui l'utilise pour ses filiales, les sociétés de son groupe ou ses clients.`,"license.who2":`Une offre payante qui l'inclut : revente, hébergement, installation ou support payants.`,"license.whoNot":`Personne d'autre : particuliers, indépendants et organisations pour leurs propres besoins n'ont rien à faire.`,"license.get":`Demander une licence Entreprise`,"license.yours":`Votre clé`,"license.key":`Clé de licence`,"license.keyDesc":`Vérifiée par harness-maxxing.com (une clé = un serveur). Rien d'autre ne change : les mises à jour viennent toujours de GitHub.`,"license.invalid":`Une clé ressemble à HM-XXXX-XXXX-XXXX-XXXX.`,"license.save":`Enregistrer la clé`,"license.none":`Aucune clé enregistrée : c'est normal si vous n'êtes pas dans un des cas ci-dessus.`,"license.active":`Clé {key} ({kind})`,"license.until":`jusqu'au {date}`,"license.remove":`Retirer la clé`,"license.removeDesc":`Libère sa place pour un autre serveur.`,"license.onbToggle":`J'ai une clé de licence Entreprise`,"license.onbToggleDesc":`Facultatif, seulement pour les entreprises qui en ont une. Modifiable plus tard dans Réglages → Licence.`,"codex.connection":`Connexion Codex`,"codex.connectionDesc":`État de la CLI utilisée par les sessions, sur cet ordinateur.`,"codex.connected":`Codex est connecté.`,"codex.notConnected":`Codex est installé mais aucune connexion active n’a été détectée.`,"codex.notInstalled":`La commande Codex est introuvable pour ce serveur.`,"codex.unknown":`Impossible de vérifier la connexion pour le moment.`,"codex.loginHint":`Une fois Codex installé, connectez-vous dans un terminal avec`,"codex.capabilities":`Fonctionnement actuel`,"codex.capabilitiesDesc":`Sessions individuelles et conversations automatiques avec Claude Code.`,"codex.limits":`Le contexte des fichiers de mémoire est partagé. Certains réglages et connecteurs propres à Claude ne sont pas encore disponibles pour Codex.`,"tint.neutral":`Neutre`,"tint.tinted":`Teinté`,"fonts.group.modern":`Modernes`,"fonts.group.character":`Avec du caractère`,"fonts.group.rounded":`Arrondies`,"fonts.group.serif":`À empattements`,"fonts.group.readable":`Faciles à lire`,"fonts.group.mono":`Monospace`,"fonts.group.system":`Cet appareil`,"density.comfortable":`Confortable`,"density.compact":`Compacte`,"accent.clay":`Orange`,"accent.blue":`Bleu`,"accent.violet":`Pourpre`,"accent.green":`Vert`,"accent.amber":`Jaune`,"accent.rose":`Rouge`,"features.browser":`Dans ce navigateur`,"features.browserDesc":`Enregistré dans ce navigateur uniquement.`,"features.server":`Pour tout le monde`,"features.serverDesc":`Enregistré sur le serveur : tous vos navigateurs et appareils en profitent.`,"features.telegramFirst":`Reliez d’abord Telegram :`,"security.change":`Changer le mot de passe`,"security.changeDesc":`Changer le mot de passe déconnecte tous les autres appareils.`,"security.current":`Mot de passe actuel`,"security.currentRequired":`Saisissez votre mot de passe actuel.`,"security.currentWrong":`Le mot de passe actuel est incorrect.`,"security.update":`Mettre à jour`,"security.changed":`Mot de passe modifié`,"security.changedDesc":`Les autres appareils ont été déconnectés.`,"security.sessions":`Appareils connectés`,"security.sessionsDesc":`Les alertes de connexion peuvent être envoyées sur Telegram (Réglages › Telegram).`,"security.everywhere":`Pour vous déconnecter partout, changez votre mot de passe : tous les cookies de session existants cessent aussitôt de fonctionner.`,"cdef.defaultModel":`Modèle par défaut`,"cdef.cliDefault":`Défaut de Claude Code`,"cdef.defaultModelHint":`Les sessions affichent le modèle qui a réellement répondu à chaque tour.`,"cdef.autoCompact":`Compaction automatique`,"cdef.autoCompactHint":`Quand un tour se termine avec plus de contexte que ce seuil, harness-pilot résume la session et continue dans un nouveau fil qui part de ce résumé (comme Compacter) : les longues sessions ne renvoient plus tout leur historique, ce qui économise des tokens. L’historique reste affiché.`,"cdef.autoCompactOff":`Désactivée`,"cdef.autoCompactRecommended":`recommandé`,"cdef.idleCompact":`Compacter au retour`,"cdef.idleCompactHint":`Le cache de prompt de Claude dure quelques minutes (une heure au plus). Quand vous écrivez dans une session inactive depuis plus longtemps, avec au moins ce contexte, harness-pilot la résume d'abord et votre message part dans un nouveau fil qui reprend ce résumé : l'historique serait de toute façon renvoyé au prix fort, les tours suivants coûtent donc beaucoup moins. Coût : un tour de résumé (une courte attente) avant la réponse.`,"cdef.smartResume":`Reprise intelligente`,"cdef.smartResumeHint":`Quand vous revenez sur une session dont le cache a expiré (voir ci-dessus) avec au moins ce contexte, ou après 5 minutes ou plus avec le double, harness-pilot fait d'abord résumer la session par Claude pour le message que vous venez d'envoyer : le résumé garde exactement ce dont votre message a besoin (fichiers, commandes, valeurs, plan en cours), puis votre message part dans un fil neuf, bien plus léger. Mesuré sur de vraies reprises : 38 à 67 % de tokens en moins dès 100k, et des détails mieux gardés qu'avec le résumé simple. Désactivé = la règle ci-dessus seule.`,"cdef.protectSecrets":`Protéger les secrets`,"cdef.protectSecretsHint":`Les outils de Claude refusent de lire ou modifier les secrets du serveur (secrets.json) et les clés SSH (~/.ssh), quel que soit le mode de permissions. Cela empêche une instruction cachée dans une page web ou un e-mail de simplement les lire ; un script écrit pour ouvrir le fichier n’est pas bloqué - pour du contenu venu de l’extérieur, préférez un mode plus strict sur ce topic.`,"cdef.shortTitles":`Titres de session courts`,"cdef.shortTitlesHint":`Une nouvelle session est nommée en quelques mots d’après son premier message (sans les « bonjour » ni « tu peux… »). Désactivé : le titre est le début du message. Renommer une session l’emporte toujours.`,"cdef.shortTitlesModel":`Titres écrits par Claude`,"cdef.shortTitlesModelHint":`Le plus petit modèle nomme le sujet (titres plus justes). Un appel rapide par nouvelle session, compté dans votre forfait Claude.`,"cdef.autoUpdate":`Mettre à jour Claude Code automatiquement`,"cdef.autoUpdateHint":`Désactivé par défaut. Activé : quand une version stable plus récente de Claude Code sort (déjà utilisée depuis quelques jours, pas la toute dernière), le serveur l’installe dès que rien n’a tourné depuis 10 minutes (aucun tour, aucun message en attente, aucune tâche planifiée), et revient à la précédente si elle ne démarre pas. Vérifié toutes les 6 heures ; le résultat apparaît dans les notifications.`,"cdef.autoUpdateLast":`Dernière mise à jour : {from} → {to}, {date}`,"cdef.autoUpdateFailed":`Échec de la mise à jour vers {to} ({date})`,"telegram.setup":`Configurer Telegram`,"telegram.setupDesc":`Environ deux minutes. Il vous faut l’application Telegram sur votre téléphone ou votre ordinateur.`,"telegram.sub.bot":`Bot`,"telegram.sub.link":`Liaison`,"telegram.sub.threads":`Fils`,"telegram.bf1":`Dans Telegram, ouvrez`,"telegram.bf2":`Envoyez la commande :`,"telegram.bf3":`Choisissez un nom affiché, puis un identifiant qui se termine par « bot » (par ex. acme_maxxing_bot).`,"telegram.bf4":`BotFather répond avec un jeton du type 123456789:AAH… : copiez-le et collez-le ci-dessous.`,"telegram.token":`Jeton du bot`,"telegram.tokenHint":`Conservé sur ce serveur. Quiconque possède le jeton contrôle le bot.`,"telegram.tokenRequired":`Collez le jeton donné par BotFather.`,"telegram.tokenInvalid":`Telegram a refusé ce jeton.`,"telegram.verify":`Vérifier le jeton`,"telegram.botOk":`Bot vérifié`,"telegram.linkIntro":`Liez maintenant votre compte Telegram : seule la conversation liée peut parler à harness-pilot.`,"telegram.link":`Lier mon Telegram`,"telegram.qr":`QR code pour ouvrir le bot`,"telegram.scan":`Scannez avec votre téléphone`,"telegram.openAndStart":`Ouvrez le bot et appuyez sur Démarrer. Cette page se met à jour toute seule une fois la liaison faite.`,"telegram.openTelegram":`Ouvrir dans Telegram`,"telegram.waiting":`En attente de /start…`,"telegram.linked":`Lié !`,"telegram.manualCode":`Ou envoyez ce message au bot :`,"telegram.chatLinked":`Conversation liée`,"telegram.threadsIntro":`Chaque session ouverte a son propre fil (plus Crons et Alertes). Archivez une session et son fil disparaît ; écrivez dans le chat principal pour en démarrer une.`,"telegram.created":`{count} fils créés`,"telegram.created#one":`{count} fil créé`,"telegram.topicsOff":`Les fils sont désactivés pour ce bot`,"telegram.topicsOff1":`Ouvrez @BotFather, envoyez /mybots puis choisissez votre bot.`,"telegram.topicsOff2":`Bot Settings › Threaded Mode › activez-le.`,"telegram.topicsOff3":`Revenez ici et appuyez sur « Réessayer ».`,"telegram.noThreads":`Aucun fil pour l’instant.`,"telegram.thread.general":`Général`,"telegram.thread.crons":`Rapports des crons`,"telegram.thread.alerts":`Alertes`,"telegram.thread.feed":`Notifications`,"telegram.status":`État`,"telegram.gateway":`Passerelle`,"telegram.running":`Active`,"telegram.stopped":`Arrêtée`,"telegram.bot":`Bot`,"telegram.chat":`Conversation liée`,"telegram.test":`Envoyer un message de test`,"telegram.testSent":`Message de test envoyé`,"telegram.behaviour":`Comportement`,"telegram.notifyCrons":`Rapports des crons`,"telegram.notifyCronsDesc":`Publier les résultats des crons dans le fil Crons (selon le réglage de chaque tâche).`,"telegram.loginAlerts":`Alertes de connexion`,"telegram.loginAlertsDesc":`Message à chaque connexion et alerte sonore après plusieurs mauvais mots de passe.`,"telegram.replyMode":`Réponses`,"telegram.replyModeDesc":`Progression en direct : un message de statut mis à jour pendant que harness-pilot travaille (sa liste de tâches et chaque étape), replié en résumé à la fin. Ou seulement la réponse finale.`,"telegram.reply.final":`Réponse finale`,"telegram.reply.progress":`Progression en direct`,"trash.title":`Corbeille`,"trash.desc":`Fichiers, topics, projets et sessions supprimés. Restaurez-les à leur place, ou supprimez-les définitivement. Les éléments de plus de {days} jours sont effacés automatiquement.`,"trash.kind.file":`fichier`,"trash.kind.folder":`dossier`,"trash.kind.topic":`topic`,"trash.kind.project":`projet`,"trash.kind.session":`session`,"trash.kind.previous_versions":`anciennes versions`,"trash.sessions":`{count} sessions`,"trash.root":`racine du workspace`,"trash.restore":`Restaurer`,"trash.restored":`Restauré dans {path}`,"trash.deleteForever":`Supprimer définitivement`,"trash.deleteConfirm":`Supprimer « {name} » définitivement ?`,"trash.deleteDesc":`Cette action est irréversible.`,"trash.empty":`Vider la corbeille`,"trash.emptyConfirm":`Vider la corbeille ?`,"trash.emptied":`Corbeille vidée`,"trash.none":`La corbeille est vide`,"trash.noneDesc":`Les fichiers, topics et sessions supprimés arrivent ici.`,"packs.title":`Projets de départ`,"packs.desc":`Des projets prêts à l’emploi selon votre activité : chaque topic connaît déjà le métier (un playbook) et vous pose quelques questions à la première session. Aucune fausse donnée. Ajoutez un pack autant de fois que vous voulez : chaque fois c’est un nouveau projet (ecommerce-2 pour une deuxième boutique…). Rien d’existant n’est jamais écrasé.`,"packs.restore":`Réinstaller`,"packs.restored":`{count} fichiers remis`,"packs.nothingMissing":`Rien ne manquait`,"packs.add":`Ajouter`,"packs.added":`Ajouté`,"packs.complete":`Ajouter les topics manquants`,"packs.jobs":`Tâches planifiées créées désactivées : {list}`,"packs.done":`{name} ajouté ({count} topics)`,"packs.doneMany":`{count} projets ajoutés`,"packs.doneMany#one":`{count} projet ajouté`,"packs.all":`Tout installer`,"packs.choose":`Choisir`,"packs.none":`Aucun`,"import.title":`Importer depuis un autre agent`,"import.desc":`Hermes, Claude Code, OpenClaw ou un autre agent : il exporte ce qu’il sait de vous sous forme de projets et de topics, vous déposez le zip ici. Rien d’existant n’est écrasé.`,"import.agent":`Votre agent actuel`,"import.other":`Autre`,"import.step1":`Copiez ce prompt et envoyez-le à votre agent actuel. Il prépare un zip avec vos projets, topics, mémoire et skills.`,"import.step2":`Déposez le zip qu’il vous donne (ou cliquez pour le choisir). Vous verrez ce qu’il contient avant tout import.`,"import.drop":`Déposez le .zip ici, ou cliquez pour le choisir`,"import.reading":`Lecture du zip…`,"import.projects":`projets`,"import.topics":`topics`,"import.skills":`Skills`,"import.files":`fichiers · {size}`,"import.new":`nouveau`,"import.merge":`existe - fusionné`,"import.rootMemory":`Votre profil et vos préférences (mémoire du workspace)`,"import.aside":`Gardé pour harness-pilot`,"import.neverOverwrite":`Les fichiers de mémoire existants reçoivent une section « Importé », les autres fichiers existants sont conservés et la copie importée est enregistrée à côté.`,"import.secrets":`{count} fichiers refusés : ils contiennent une clé ou un token`,"import.secretsHint":`Ajoutez vos clés dans Réglages → Clés - jamais dans les fichiers de mémoire.`,"import.skipped":`{count} fichiers ignorés`,"import.apply":`Importer`,"import.done":`Importé : {projects} projets, {topics} topics, {files} fichiers.`,"import.mergedInto":`{count} fichiers de mémoire existants ont reçu une section « Importé ».`,"import.finish":`Laisser harness-pilot finir l’import`,"import.finishTitle":`Finir l’import`,"import.finishHint":`harness-pilot range la mémoire importée, crée vos tâches, propose vos tâches planifiées et liste les clés à ajouter.`,"import.finishing":`harness-pilot finit l’import (tâches, tâches planifiées, clés à ajouter) - vous le retrouverez dans Sessions.`,"import.copy":`Copier le prompt`,"import.copied":`Copié`,"import.skillsN":`skills`,"trash.loadFailed":`Impossible de charger la corbeille`,"trash.loadFailedDesc":`Vérifiez votre connexion ou vos droits d’accès, puis réessayez.`,"telegram.threads":`Fils`,"telegram.threadsDesc":`Un par session ouverte, synchronisés automatiquement. Supprimer un fil dans Telegram archive sa session (rien n’est perdu).`,"telegram.mirrorWeb":`Afficher les conversations web dans Telegram`,"telegram.mirrorWebDesc":`Ce que vous écrivez dans l’interface web et les réponses de harness-pilot apparaissent aussi dans le fil de la session, en silencieux (la cloche d’une session fait sonner ses réponses).`,"telegram.threadDays":`Garder un fil pendant`,"telegram.threadDaysDesc":`Les sessions ouvertes inactives plus longtemps perdent leur fil (elles restent dans l’interface web et le retrouvent au prochain message).`,"telegram.days":`{count} jours`,"telegram.threadDaysConfirm":`Supprimer {count} fils ?`,"telegram.threadDaysConfirm#one":`Supprimer {count} fil ?`,"telegram.threadDaysConfirmDesc":`Leurs sessions sont inactives depuis plus longtemps que la nouvelle limite : leurs fils et les messages qu’ils contiennent sont supprimés de Telegram. Les sessions restent dans l’interface web et retrouvent un fil à leur prochain message.`,"telegram.threadDaysConfirmOk":`Supprimer les fils`,"telegram.thread.session":`session`,"telegram.sync":`Synchroniser les fils`,"telegram.unlink":`Déconnecter Telegram`,"telegram.unlinkDesc":`Oublie le jeton du bot, la conversation liée et les fils. Les sessions restent dans l’interface web.`,"telegram.unlinkConfirm":`Déconnecter Telegram ?`,"telegram.topicsOffDesc":`Tout fonctionne dans la conversation principale. Pour avoir un fil par session, activez le Threaded Mode du bot :`,"telegram.topicsStillOff":`Les fils sont toujours désactivés pour ce bot : vérifiez le Threaded Mode dans @BotFather.`,"telegram.retry":`Réessayer`,"telegram.changeBot":`Changer de bot`,"telegram.changeBotHint":`Collez le jeton d’un autre bot, ou le nouveau jeton de ce bot. Rien ne change tant que le jeton n’est pas vérifié ; un autre bot devra être lié à nouveau.`,"telegram.newLink":`Nouveau lien`,"telegram.expiresIn":`Valable encore {time}`,"telegram.expired":`Ce lien a expiré`,"telegram.expiredDesc":`Un lien est valable 15 minutes. Créez-en un nouveau, puis ouvrez-le dans Telegram.`,"telegram.startEarly":`Vous avez déjà appuyé sur Démarrer dans Telegram ? Ouvrez ce lien (ou scannez le code) maintenant : il envoie le code.`,"telegram.relink":`Lier une autre conversation`,"telegram.relinkDesc":`Ouvrez ce lien depuis le compte Telegram à utiliser : il remplace la conversation liée (le bot reste le même).`,"telegram.newToken":`Nouveau jeton du bot`,"telegram.tokenRejected":`Telegram a refusé le jeton du bot`,"telegram.tokenRejectedDesc":`Le jeton a été révoqué ou remplacé dans @BotFather : le bot ne reçoit plus rien. Collez le nouveau jeton (même bot : la conversation et les fils sont conservés).`,"telegram.removeWebhook":`Supprimer le webhook`,"telegram.err.webhook_set":`Ce bot envoie ses messages à un webhook : un autre programme l’utilise`,"telegram.err.webhookHelp":`Supprimez le webhook pour utiliser le bot ici (l’autre programme ne recevra plus ses messages), ou créez un bot dédié avec @BotFather.`,"telegram.err.conflict":`Un autre programme (n8n, Hermes, OpenClaw…) utilise déjà ce bot : arrêtez-le, ou créez un bot dédié avec @BotFather.`,"telegram.err.webhook_check_failed":`Impossible de vérifier si un autre programme utilise ce bot. Réessayez dans un instant.`,"telegram.err.unreachable":`Telegram est injoignable. Réessayez dans un instant.`,"telegram.pollErrorTitle":`Réception des messages`,"telegram.syncErrorTitle":`Synchronisation des fils`,"telegram.lastPoll":`Dernière réponse de Telegram`,"telegram.never":`jamais`,"telegram.testProblems":`Message de test envoyé, mais :`,"telegram.testNotSent":`Le message de test n’a pas été envoyé :`,"backup.whyTitle":`Pourquoi sauvegarder ?`,"backup.why":`Vos fichiers mémoire sont ce qui rend harness-pilot utile dans la durée. Si ce serveur meurt, une sauvegarde permet à l’installateur de les restaurer sur un nouveau en une minute. Seule une liste blanche de fichiers texte est envoyée, et un détecteur bloque tout ce qui ressemble à une clé.`,"backup.gh1":`Créez un jeton « fine-grained » sur`,"backup.gh2":`Accès aux dépôts : « All repositories » si le dépôt doit être créé pour vous, sinon uniquement le dépôt de sauvegarde.`,"backup.gh3":`Permissions :`,"backup.gh3b":`(la seconde uniquement pour créer le dépôt).`,"backup.gh4":`Générez le jeton, copiez-le et collez-le ci-dessous.`,"backup.repo":`Dépôt`,"backup.repoHint":`proprietaire/nom — il doit être privé.`,"backup.repoInvalid":`Utilisez la forme proprietaire/nom.`,"backup.token":`Jeton GitHub`,"backup.tokenRequired":`Collez le jeton GitHub.`,"backup.create":`Créer le dépôt privé pour moi`,"backup.createHint":`S’il n’existe pas encore. Nécessite la permission Administration.`,"backup.connect":`Vérifier et enregistrer`,"backup.configFailed":`GitHub a refusé l’accès.`,"backup.notPrivate":`Ce dépôt est public : la sauvegarde refuse d’y pousser.`,"backup.connected":`Dépôt de sauvegarde connecté`,"backup.private":`Privé`,"backup.runFirst":`Lancer la première sauvegarde`,"backup.runNow":`Sauvegarder maintenant`,"backup.runOk":`Sauvegarde terminée`,"backup.runOkDesc":`{files} fichiers, commit {commit}.`,"backup.runFailed":`La sauvegarde a échoué`,"backup.repository":`Dépôt`,"backup.repositoryDesc":`Où votre mémoire est envoyée.`,"backup.settings":`Planification et contenu`,"backup.schedule":`Planification`,"backup.scheduleHint":`Expression cron, dans votre fuseau horaire.`,"backup.scheduleInvalid":`Expression cron invalide.`,"backup.include":`Fichiers inclus`,"backup.includeHint":`Les motifs grisés sont toujours inclus. Ajoutez des motifs relatifs à l’espace de travail.`,"backup.always":`Toujours inclus`,"backup.addGlob":`Ajouter un motif`,"backup.history":`Historique`,"backup.historyDesc":`Une restauration place d’abord les fichiers actuels dans la corbeille.`,"backup.noHistory":`Aucune sauvegarde pour l’instant`,"backup.noHistoryDesc":`Les exécutions apparaîtront ici.`,"backup.filesCount":`{count} fichiers`,"backup.filesCount#one":`{count} fichier`,"backup.changedCount":`{count} modifiés`,"backup.restore":`Restaurer`,"backup.restoreTitle":`Restaurer cette sauvegarde ?`,"backup.restoreDesc":`Les fichiers de la liste blanche, les crons et les réglages sont remplacés par cette version. Les fichiers actuels sont d’abord placés dans la corbeille.`,"backup.restored":`{count} fichiers restaurés`,"backup.restored#one":`{count} fichier restauré`,"backup.forget":`Déconnecter la sauvegarde`,"backup.forgetDesc":`Oublie le dépôt et le jeton. Le dépôt lui-même n’est pas supprimé.`,"backup.forgetConfirm":`Déconnecter la sauvegarde ?`,"mcp.whatTitle":`Les serveurs MCP donnent de nouveaux outils à Claude`,"pc.candidateTitle":`{name} demande à se connecter`,"pc.candidateFrom":`Il s’est connecté depuis {ip} à {time}. Si ce n’est pas l’adresse de votre ordinateur, refusez.`,"pc.candidateDesc":`Un ordinateur {os} a utilisé votre téléchargement. Est-ce bien le vôtre ? Tant que vous ne confirmez pas, Claude ne peut pas l’utiliser. Si vous ne le reconnaissez pas, refusez : il est déconnecté et oublie ce serveur.`,"pc.candidateYes":`Oui, c’est mon PC`,"pc.candidateNo":`Refuser`,"pc.title":`Navigateur de mon PC`,"pc.desc":`Claude utilise un navigateur sur votre propre ordinateur : un profil séparé de votre navigateur, ouvert seulement quand Claude en a besoin.`,"pc.whichOs":`Votre ordinateur`,"pc.whichBrowser":`Navigateur utilisé par Claude`,"pc.isolated":`Claude a son propre profil {browser} : vos onglets, mots de passe et historique habituels ne sont jamais touchés. Connectez-vous-y une fois aux sites dont Claude a besoin.`,"pc.autostart":`Démarrer avec l’ordinateur`,"pc.autostartDesc":`harness-pilot PC attend en arrière-plan (presque aucun processeur ni mémoire) et n’ouvre le navigateur que lorsque Claude en a besoin. Désactivé : lancez-le vous-même quand vous voulez que Claude navigue.`,"pc.prepare":`Obtenir harness-pilot PC`,"pc.step.downloadWin":`Téléchargez HarnessPC.exe (il est déjà relié à ce serveur).`,"pc.step.download":`Téléchargez harness-pilot PC (il est déjà relié à ce serveur).`,"pc.step.runWin":`Ouvrez-le depuis vos Téléchargements. Si Windows affiche « Windows a protégé votre ordinateur », cliquez sur Informations complémentaires, puis Exécuter quand même.`,"pc.step.run":`Lancez-le (ou collez la commande ci-dessous dans un terminal).`,"pc.step.wait":`Cette page vous demande ensuite de confirmer que c’est bien votre PC. {browser} ne s’ouvre que lorsque Claude l’utilise.`,"pc.downloadWin":`Télécharger pour Windows`,"pc.downloadLinux":`Télécharger pour Linux`,"pc.downloadMacArm":`Télécharger pour Mac (puce Apple)`,"pc.downloadMacIntel":`Mac avec puce Intel`,"pc.orCommandWin":`Ou collez ceci dans PowerShell :`,"pc.orCommand":`Ou collez ceci dans un terminal :`,"pc.smartscreenTitle":`Windows peut afficher un avertissement`,"pc.smartscreen":`harness-pilot PC n’est pas encore signé par un éditeur, donc SmartScreen demande une confirmation : Informations complémentaires, puis Exécuter quand même. Il n’a pas besoin des droits administrateur et n’ouvre que le navigateur choisi.`,"pc.waiting":`En attente de votre PC… (lien valable {left})`,"pc.expired":`Ce téléchargement a expiré : obtenez-en un nouveau.`,"pc.connected":`{name} est connecté`,"pc.computer":`Ordinateur`,"pc.state":`État`,"pc.lastUse":`Dernière utilisation`,"pc.never":`jamais`,"pc.offline":`Hors ligne`,"pc.ready":`Prêt (navigateur fermé)`,"pc.inUse":`{browser} ouvert pour Claude`,"pc.offlineTitle":`Votre PC n’est pas connecté`,"pc.offlineDesc":`harness-pilot PC n’est pas lancé, ou l’ordinateur est éteint ou en veille. Lancez harness-pilot PC dessus ; en attendant, Claude est prévenu que le PC est hors ligne.`,"pc.mcpMissing":`Claude ne voit pas encore les outils du navigateur : rechargez cette page dans un instant ; si cela reste, utilisez Réinstaller.`,"pc.test":`Tester`,"pc.testOk":`Le navigateur de votre PC a répondu`,"pc.testFail":`Le navigateur n’a pas répondu`,"pc.stop":`Arrêter maintenant`,"pc.wipe":`Effacer le profil`,"pc.wipeConfirm":`Effacer le profil utilisé par Claude ?`,"pc.wipeDesc":`Ses cookies, connexions et historique sur votre PC sont supprimés. Votre navigateur habituel n’est pas touché.`,"pc.wiped":`Profil effacé`,"pc.reinstall":`Réinstaller / autre PC`,"pc.unpair":`Déconnecter`,"pc.unpairConfirm":`Déconnecter ce PC ?`,"pc.unpairDesc":`harness-pilot PC s’arrête et se retire du démarrage ; Claude perd les outils du navigateur. Le profil reste sur le PC tant que vous ne l’effacez pas.`,"pc.idle":`Fermer le navigateur après`,"pc.idleDesc":`Sans aucune action de Claude dans le navigateur pendant ce temps, le navigateur et ses outils s’arrêtent.`,"pc.recent":`Actions récentes`,"mcp.whatExplain":"Un serveur ajouté pour « Toutes les sessions » est disponible partout ; ajouté à un topic, seulement dans les sessions de ce topic. Les secrets restent dans Réglages → Clés et s’écrivent ${NOM_DE_CLE}. Vous pouvez aussi simplement demander à Claude dans un topic : « connecte le MCP … ».","mcp.servers":`Serveurs MCP`,"mcp.autoTitle":`Chargement`,"mcp.auto":`Charger les serveurs MCP seulement quand une session en a besoin`,"mcp.autoHint":"Chaque serveur chargé coûte des tokens à chaque message et ralentit le début d’un tour. Activé, une session reçoit les serveurs déjà utilisés dans son topic, ceux nommés dans votre message et ceux ajoutés à son topic ; Claude peut en demander un autre (`maxxing mcp load`) et harness-pilot continue tout seul. Si un connecteur claude.ai est nécessaire, tout est chargé, comme avant. Le Navigateur de mon PC est toujours là.","mcp.serversDesc":`Les serveurs que Claude Code charge dans ce workspace.`,"mcp.checkedAt":`États vérifiés {when}.`,"mcp.check":`Vérifier`,"mcp.checking":`Vérification…`,"mcp.add":`Ajouter un serveur`,"mcp.addDesc":`L’adresse (ou la commande) est donnée par la documentation du service.`,"mcp.empty":`Aucun serveur MCP`,"mcp.emptyDesc":`Ajoutez-en un ici, ou demandez à Claude dans le topic qui en a besoin.`,"mcp.name":`Nom`,"mcp.where":`Où`,"mcp.whereHint":`Toutes les sessions, ou seulement celles d’un topic.`,"mcp.searchTopic":`Chercher un topic`,"mcp.everywhere":`Toutes les sessions`,"mcp.stateCol":`État`,"mcp.type":`Type`,"mcp.typeHttp":`Adresse (URL)`,"mcp.typeStdio":`Programme local`,"mcp.url":`Adresse`,"mcp.command":`Commande`,"mcp.headers":`En-têtes (facultatif)`,"mcp.env":`Variables d’environnement (facultatif)`,"mcp.addLine":`Ajouter une ligne`,"mcp.insertKey":`Insérer une clé du coffre`,"mcp.noKeys":`Aucune clé dans Réglages → Clés`,"mcp.keysHint":"Une clé écrite ${NOM_DE_CLE} est lue dans le coffre au démarrage de la session (elle est fournie aux sessions automatiquement). Les serveurs avec un bouton « Connecter » n’ont pas besoin de clé.","mcp.literalWarn":"Ça ressemble à un jeton écrit en clair : mieux vaut le mettre dans Réglages → Clés et écrire ${NOM_DE_CLE}.","mcp.literal":`jeton en clair`,"mcp.nameInvalid":`Lettres, chiffres, « . », « _ » et « - » seulement.`,"mcp.urlInvalid":`L’adresse commence par https://`,"mcp.commandRequired":`Indiquez la commande qui lance le serveur.`,"mcp.added":`{name} ajouté`,"mcp.addedExposed":`{name} ajouté - clés désormais fournies aux sessions : {keys}`,"mcp.state.connected":`Connecté`,"mcp.state.needs_auth":`À connecter`,"mcp.state.failed":`Erreur`,"mcp.state.pending":`À approuver`,"mcp.state.unknown":`Non vérifié`,"mcp.connect":`Connecter`,"mcp.reconnect":`Reconnecter`,"mcp.connectTitle":`Connecter {name}`,"mcp.connectDesc":`Une seule fois, en quatre étapes : la connexion est ensuite gardée pour toutes les sessions.`,"mcp.preparing":`Préparation de la page de connexion…`,"mcp.step1":`Ouvrez la page de connexion du service`,"mcp.openLogin":`Ouvrir la page de connexion`,"mcp.step2":`Connectez-vous chez {service} et acceptez`,"mcp.step3":`Vous arrivez sur une page d’erreur : c’est normal`,"mcp.step3Desc":`Le service vous renvoie vers une adresse du serveur harness-pilot (« localhost ») que votre navigateur ne peut pas ouvrir : il affiche « Ce site est inaccessible ». La connexion n’est pas finie : le code est dans l’adresse.`,"mcp.browserError":`Ce site est inaccessible - localhost n’autorise pas la connexion.`,"mcp.step3Copy":`Copiez toute l’adresse de la barre d’adresse (cliquez dessus, puis Ctrl+C / ⌘C). Sur téléphone : appui long sur l’adresse, Copier.`,"mcp.step4":`Revenez ici et collez-la`,"mcp.paste":`Coller`,"mcp.pasteDenied":`Le navigateur a refusé : collez avec Ctrl+V / ⌘V dans le champ.`,"mcp.noCode":`Cette adresse ne contient pas « code= » : copiez l’adresse de la page d’erreur, après avoir accepté.`,"mcp.whyTitle":`Pourquoi ce copier-coller ?`,"mcp.whyBody":`Claude Code, qui tourne sur votre serveur, attend la réponse du service sur une adresse locale du serveur. Le service ne peut renvoyer votre navigateur que vers cette adresse, qui n’existe que sur le serveur. En la collant, vous donnez le code à Claude Code, qui termine la connexion. Ça marche quel que soit l’accès (domaine, Tailscale), sans rien d’autre à faire. À faire en quelques minutes : le code expire.`,"mcp.finish":`Terminer`,"mcp.retry":`Réessayer`,"mcp.connected":`{name} est connecté`,"mcp.chatHint":`L'agent a besoin de cette connexion. Une fois faite, dis-lui de réessayer.`,"mcp.chatConnected":`{name} était connecté au dernier contrôle : reconnectez-le si l'agent le demande encore.`,"mcp.remove":`Retirer`,"mcp.removeTitle":`Retirer {name} ?`,"mcp.removeDesc":`Claude n’aura plus ses outils à cet endroit. Les clés du coffre sont gardées.`,"keys.vault":`Coffre`,"keys.vaultDesc":`Les valeurs ne quittent jamais le serveur, sauf si vous les révélez.`,"keys.add":`Ajouter une clé`,"keys.edit":`Modifier la clé`,"keys.dialogDesc":`Enregistrée dans le fichier de secrets du serveur (mode 600).`,"keys.name":`Nom`,"keys.nameHint":`Style variable d’environnement : OPENAI_API_KEY.`,"keys.nameInvalid":`Lettres, chiffres et tirets bas, en commençant par une lettre.`,"keys.value":`Valeur`,"keys.valueKeep":`Laissez vide pour garder la valeur actuelle.`,"keys.valueRequired":`Saisissez une valeur.`,"keys.note":`Note`,"keys.notePlaceholder":`À quoi elle sert, d’où elle vient`,"keys.noNote":`Sans note`,"keys.expose":`Fournir aux sessions harness-pilot`,"keys.exposeShort":`Exposée`,"keys.unexpose":`Ne plus exposer`,"keys.exposeDesc":`Exportée comme variable d’environnement à chaque tour de harness-pilot.`,"keys.exposeTitle":`Clés exposées`,"keys.exposeExplain":`Une clé exposée est disponible pour harness-pilot comme variable d’environnement (par ex. $OPENAI_API_KEY) dans chaque session et chaque cron : les scripts peuvent l’utiliser sans que la valeur apparaisse dans un prompt. harness-pilot peut quand même la lire : n’exposez que ce dont les sessions ont besoin.`,"keys.reveal":`Révéler`,"keys.copied":`{name} copiée`,"keys.added":`Clé ajoutée`,"keys.updated":`Clé mise à jour`,"keys.deleteTitle":`Supprimer {name} ?`,"keys.deleteDesc":`Les scripts et sessions qui l’utilisent cesseront de fonctionner.`,"keys.empty":`Aucune clé`,"keys.emptyDesc":`Rangez ici vos clés d’API et jetons plutôt que dans des fichiers.`,"features.git":`Page Git & GitHub`,"features.gitDesc":`Une entrée « Git » dans la barre latérale : tous les dépôts du serveur et de votre compte GitHub avec vos droits, leurs branches et commits en graphe. Les graphes dans les conversations restent là dans tous les cas. Pour GitHub, ajoutez la clé GITHUB_TOKEN dans`,"features.infra":`Page Infra`,"features.infraDesc":`Une entrée « Infra » dans la barre latérale : chaque site, base de données, bucket, domaine et serveur - ce serveur, vos autres serveurs (SSH), Cloudflare, Hostinger - avec son état, ses liens et où il se trouve. En lecture seule ; Claude crée sites, bases et buckets de façon standard. Pour Cloudflare et Hostinger, ajoutez leurs clés dans`,"features.maxxing":`Mode Pilot (bêta)`,"features.maxxingDesc":`Un bouton « ⚡ Pilot » sur la page Sessions (Alt+M), à activer dans chaque navigateur : dès qu’une session finit, elle passe devant, seule, à la place des autres colonnes, pour que vous tapiez la suite tout de suite. Désactivé, vos colonnes reviennent.`,"system.health":`Santé`,"system.healthDesc":`Actualisée toutes les 30 secondes.`,"system.claudeAuth":`Authentification Claude`,"system.notConnected":`Non connecté`,"system.backupAge":`Dernière sauvegarde`,"system.never":`Jamais`,"system.hoursAgo":`il y a {n} h`,"system.failedLogins":`Connexions échouées (1 h)`,"system.load":`Charge moyenne`,"system.services":`Services`,"system.servicesDesc":`Unités systemd utiles à harness-pilot.`,"system.disabled":`Désactivé`,"system.start":`Démarrer`,"system.stop":`Arrêter`,"system.restart":`Redémarrer`,"system.stopTitle":`Arrêter {name} ?`,"system.restartTitle":`Redémarrer {name} ?`,"system.serviceConfirm":`Le travail en cours géré par ce service peut être interrompu.`,"system.selfRestart":`L’interface est hors ligne quelques secondes puis se reconnecte seule. Les tours de harness-pilot en cours ne sont pas affectés.`,"system.actionDone":`{name} : fait`,"system.logs":`Journaux`,"system.unit":`Service`,"system.lines":`{n} lignes`,"system.linesLabel":`Nombre de lignes`,"system.noLogs":`Aucune ligne de journal.`,"system.version":`Version`,"system.upToDate":`À jour`,"system.behind":`{n} mises à jour disponibles`,"system.unknownLatest":`Dernière version inconnue`,"system.unknownLatestDesc":"GitHub est injoignable avec le jeton de mise à jour. Lancez `maxxing update --check` sur le serveur pour voir pourquoi (jeton expiré, pas de réseau).","system.check":`Vérifier`,"system.checkFailed":`La vérification a échoué`,"system.checkedAt":`vérifié {when}`,"system.update":`Mettre à jour`,"system.updateTitle":`Mettre à jour harness-pilot ?`,"system.updateDesc":`Télécharge la nouvelle version, installe les dépendances et redémarre le service (environ une minute). Vos données, votre espace de travail et vos extensions sont conservés.`,"system.updating":`Mise à jour…`,"system.restarting":`Redémarrage du serveur…`,"system.updated":`Mise à jour installée`,"system.autoUpdate":`Se mettre à jour seul quand personne n'est là`,"system.autoUpdateHint":`Désactivé par défaut. Activé : quand une nouvelle version est sortie, que personne n'est sur l'interface, que rien ne tourne (ni session, ni job, rien depuis 10 minutes) et que la mise à jour ne touche pas à vos personnalisations, harness-pilot se met à jour seul puis redémarre quelques secondes. Sinon il attend et vous prévient dans les notifications.`,"system.updatedDesc":`Rechargez la page pour utiliser la nouvelle version.`,"system.customs":`{count} personnalisations du code, conservées à chaque mise à jour`,"system.customs#one":`{count} personnalisation du code, conservée à chaque mise à jour`,"system.license":`Licence {key} ({kind}) - {email}`,"system.licenseKind.paid":`payée`,"system.licenseKind.beta":`bêta`,"system.licenseKind.gift":`offerte`,"system.licenseKind.enterprise":`entreprise`,"system.licenseUpdatesUntil":`mises à jour jusqu’au {date}`,"system.licenseUpdatesEnded":`mises à jour terminées le {date} : ce serveur continue sur sa version`,"system.licenseUpdatesForever":`mises à jour incluses`,"system.licenseMoving":`Passage aux mises à jour GitHub en attente : {error}. Nouvel essai toutes les 6 h.`,"system.movedToGit":`Mises à jour depuis GitHub (branche stable) depuis le {date}, comme toutes les installations. Clé {key} gardée.`,"system.pendingConflict":`La mise à jour {version} attend harness-pilot`,"system.pendingConflictDesc":`Vos personnalisations entrent en conflit avec la nouvelle version. Rien n’a changé : la version actuelle continue de tourner. harness-pilot peut les adapter dans le projet system (topic harness).`,"system.pendingRolledBack":`La mise à jour {version} a été annulée`,"system.pendingRolledBackDesc":`La nouvelle version n’a pas démarré : l’ancienne a été remise automatiquement, rien n’est perdu. Demandez à harness-pilot dans le projet system (topic harness) de regarder.`,"system.askClaude":`Demander à harness-pilot`,"update.checking":`Vérification de ce que cette mise à jour change sur votre serveur…`,"update.simpleTitle":`Prêt à mettre à jour`,"update.simpleTitleCustoms":`Compatible : vos {count} modifications sont conservées`,"update.simpleTitleCustoms#one":`Compatible : votre modification est conservée`,"update.simpleDesc":`Testé sur une copie de votre serveur, rien n’a encore changé. Après la mise à jour, vos extensions et modifications sont vérifiées automatiquement.`,"update.adaptTitle":`Certaines de vos modifications doivent d’abord être adaptées`,"update.adaptDesc":`harness-pilot les adapte à la nouvelle version (à quoi sert chaque modification est enregistré), teste, puis met à jour. Votre version actuelle continue de tourner tant que tout ne marche pas.`,"update.withHarness":`Mettre à jour avec harness-pilot`,"update.assistFailed":`Impossible d’ouvrir la session de mise à jour`,"update.custom.ok":`conservée`,"update.custom.review":`conservée, sur du code qui a changé (vérifiée après la mise à jour)`,"update.custom.included":`désormais incluse dans la nouvelle version`,"update.custom.conflict":`à adapter à la nouvelle version`,"update.custom.unknown":`n’a pas pu être vérifiée`,"update.unsaved":`{count} modifications du code non enregistrées, sauvegardées par la mise à jour`,"update.unsaved#one":`1 modification du code non enregistrée, sauvegardée par la mise à jour`,"update.webChanges":`{count} retouches des fichiers de l’interface : harness-pilot les refait en extension`,"update.webChanges#one":`1 retouche des fichiers de l’interface : harness-pilot la refait en extension`,"update.extension":`L’extension « {name} » doit être mise à jour pour la nouvelle version`,"update.notes":`{count} nouveautés à appliquer dans votre espace : harness-pilot s’en charge juste après`,"update.notes#one":`Une nouveauté à appliquer dans votre espace : harness-pilot s’en charge juste après`,"update.problems":`Après la mise à jour {version} : {count} éléments ne marchent plus`,"update.problems#one":`Après la mise à jour {version} : 1 élément ne marche plus`,"update.problemsDesc":`Une extension ou une de vos modifications ne fonctionne plus avec cette version. harness-pilot peut la réparer.`,"update.fix":`Réparer avec harness-pilot`,"update.verified":`Vérifié après la mise à jour : vos extensions et modifications fonctionnent.`,"update.verifyLong":`Vérifier que vos extensions et modifications fonctionnent`,"update.verify":`Vérifier maintenant`,"update.allGood":`Tout fonctionne`,"update.notesSession":`harness-pilot applique les nouveautés de cette version.`,"update.openSession":`Ouvrir la session`,"nset.device":`Sur cet appareil`,"nset.deviceDesc":`Ces réglages ne valent que pour ce navigateur.`,"nset.perm.granted":`Autorisées par le navigateur`,"nset.perm.denied":`Bloquées par le navigateur`,"nset.perm.default":`Pas encore autorisées`,"nset.perm.unsupported":`Pas de notifications système`,"nset.allow":`Autoriser`,"nset.test":`Envoyer un test`,"nset.testSent":`Test envoyé : il arrive dans quelques secondes`,"nset.push":`Recevoir même quand l’app est fermée`,"nset.pushDesc":`Notifications push, sur ordinateur comme sur l’app installée du téléphone, pour les événements cochés « Navigateur » ci-dessous.`,"nset.pushServer":`Votre serveur n’envoie pas encore de notifications push : mettez-le à jour pour activer ceci.`,"nset.pushOrigin":`Demande l’app installée ou une adresse HTTPS (le service worker ne tourne pas ici).`,"nset.pushIos":`Sur iPhone et iPad : ajoutez d’abord l’app à l’écran d’accueil (Partager → Sur l’écran d’accueil), puis activez ceci depuis l’app.`,"nset.pushFailed":`Impossible d’activer les notifications push`,"nset.pulse":`Pastilles scintillantes`,"nset.pulseDesc":`Les compteurs non lus scintillent jusqu’à ce que vous les ouvriez.`,"nset.what":`Quoi et où`,"nset.whatDesc":`Tout arrive dans le centre de notifications. Choisissez ce qui vous dérange en plus.`,"nset.browserHint":`Navigateur : un bandeau dans l’app, et une notification système quand elle est en arrière-plan ou fermée.`,"nset.telegramOn":`Telegram activé`,"nset.telegramOld":`Ce serveur règle Telegram par source : mettez-le à jour pour choisir par événement.`,"nset.col.event":`Événement`,"nset.col.browser":`Navigateur`,"nset.col.telegram":`Telegram`,"nset.browserLabel":`{event} dans ce navigateur`,"nset.telegramLabel":`{event} dans Telegram`,"nset.tg.off":`Non`,"nset.tg.silent":`Silencieux`,"nset.tg.loud":`Avec son`,"nset.tg.auto":`Selon le niveau`,"nset.tg.autoIs":`Par défaut : {rule}`,"nset.group.sessions":`Sessions`,"nset.group.crons":`Crons`,"nset.group.system":`Système`,"nset.group.webhooks":`Webhooks et scripts`,"nset.row.session.done":`Session terminée`,"nset.row.session.failed":`Tour en échec`,"nset.row.discussion.paused":`Discussion en pause`,"nset.row.discussion.pausedHint":`(limite atteinte)`,"nset.row.cron.failed":`Cron en échec`,"nset.row.cron.succeeded":`Crons réussis`,"nset.row.cron.succeededHint":`(regroupés)`,"nset.row.updates":`Mises à jour`,"nset.row.health":`Santé du serveur`,"nset.row.security":`Connexions et sécurité`,"nset.row.signins":`Connexions réussies`,"nset.row.infra":`Sites et domaines`,"nset.noScripts":`Aucun webhook ni script n’a encore publié.`,"nset.sources":`Sources externes`,"nset.sourcesDesc":`Webhooks Stripe, Shopify, GitHub ou JSON, et scripts via maxxing feed post.`,"nset.secretMissing":`Secret manquant · événements refusés`,"nset.noHooks":`Aucun webhook pour l’instant : ajoutez-en un pour recevoir ici ventes, commandes ou workflows en échec.`,"nset.more":`Plus d’actions pour {name}`,"nset.team":`Messages Team`,"nset.sound":`Son des notifications`,"nset.soundHint":`Un son différent selon l’importance : erreur, alerte, réussite. Les événements cochés dans la colonne « Son » le jouent.`,"nset.soundSet.chime":`Carillon`,"nset.soundSet.soft":`Discret`,"nset.soundSet.none":`Aucun`,"nset.volume":`Volume`,"nset.volumeLabel":`Volume des notifications`,"nset.listen":`Écouter`,"nset.col.sound":`Son`,"nset.soundLabel":`{event} avec son`,"nset.soundOff":`Choisissez d’abord un son ci-dessus.`,"memory.title":`Nettoyage du second cerveau`,"memory.desc":`Garde chaque memory.md court et bien rangé : doublons fusionnés, contradictions réglées, historique ancien résumé, sections ordonnées. Tourne chaque nuit (tâche « Memory compaction ») et à la demande.`,"memory.cleanNow":`Nettoyer maintenant`,"memory.limit":`Longueur maximale par fichier`,"memory.limitDesc":`Les fichiers plus longs sont compactés et réorganisés pour tenir dessous (vers 80 %, pour garder de la marge).`,"memory.lines":`{count} lignes`,"memory.noLimit":`Aucune limite`,"memory.daily":`Nettoyage nocturne`,"memory.dailyDesc":`La tâche « Memory compaction » tourne à 5 h par défaut : changez son horaire ou coupez-la dans Crons.`,"memory.openCrons":`Ouvrir Crons`,"memory.files":`Fichiers mémoire`,"memory.filesDesc":`Tous les memory.md de l'espace de travail.`,"memory.overCount":`{count} fichiers dépassent {limit} lignes - « Nettoyer maintenant » les corrige.`,"memory.overCount#one":`{count} fichier dépasse {limit} lignes - « Nettoyer maintenant » le corrige.`,"memory.allUnder":`Tous les fichiers font moins de {limit} lignes.`,"memory.none":`Aucun fichier mémoire pour le moment`,"memory.file":`Fichier`,"memory.lineCount":`Lignes`,"memory.size":`Taille`,"memory.started":`Nettoyage lancé`,"memory.startedDesc":`harness-pilot compacte les fichiers mémoire dans une nouvelle session.`,"stats.quota":`Quota du forfait Claude`,"stats.quotaDesc":`Part utilisée des limites de votre abonnement Claude (la semaine, et la fenêtre de 5 h si votre forfait en a une).`,"stats.quotaEnable":`Afficher l'utilisation du forfait`,"stats.quotaEnableDesc":`Expérimental : lu sur un point d'accès Anthropic non documenté, peut cesser de fonctionner. Ajoute aussi le widget du tableau de bord.`,"stats.fiveHour":`Fenêtre de 5 h en cours`,"stats.plan":`Forfait : Claude {plan}`,"stats.noFiveHour":`Pas de fenêtre de 5 h : le forfait Ultra n'a que la limite de la semaine.`,"stats.sevenDay":`Cette semaine`,"stats.resets":`remise à zéro {at}`,"stats.stale":`Dernières valeurs connues (le point d'accès n'a pas répondu à l'instant).`,"stats.quotaUnavailable":`L'utilisation du forfait n'est pas disponible avec cette méthode de connexion.`,"stats.reason.no_oauth_credentials":`Le quota est indisponible : les identifiants accessibles au serveur ne permettent pas sa lecture. Sur macOS, Claude peut être connecté via le trousseau même si ce quota reste indisponible.`,"stats.reason.api_key":`L'utilisation du forfait n'existe qu'avec un abonnement Claude ; ce serveur utilise une clé API.`,"stats.reason.rate_limited":`Anthropic limite la fréquence de lecture de l'utilisation - prochaine lecture {when}.`,"stats.reason.http_401":`La connexion Claude a été refusée : reconnectez-vous (Réglages -> Claude).`,"stats.reason.other":`Impossible de lire l'utilisation du forfait ({code}).`,"stats.nextReading":`Prochaine lecture {when}.`,"stats.tokens":`Tokens`,"stats.tokensDesc":`Comptés sur les tours enregistrés, sessions archivées comprises. Les anciens totaux Codex peuvent surestimer les tokens mis en cache ; les nouveaux tours sont corrigés.`,"stats.byAgent":`Consommation par agent`,"stats.agentHint":`Suivi disponible pour les nouveaux tours ; {count} anciens tours ou tours sans données ne sont pas répartis par agent.`,"stats.empty":`Aucun tour de harness-pilot pour le moment`,"stats.total":`Tokens`,"stats.turns":`{count} tours`,"stats.turns#one":`{count} tour`,"stats.turnsCol":`Tours`,"stats.inOut":`Entrée / sortie`,"stats.cache":`Cache lu / écrit`,"stats.cacheHint":`relectures de contexte depuis le cache`,"stats.turnStart":`Démarrage d’un tour (médiane)`,"stats.turnStartHint":`première réponse après {first} s · {count} derniers tours`,"stats.cost":`Coût`,"stats.costHint":`montant indicatif Claude ; vérifiez votre facture auprès d’Anthropic`,"stats.perDay":`Tokens par jour (30 jours)`,"stats.groupBy":`Regrouper par`,"stats.byProject":`Projet`,"stats.byTopic":`Topic`,"stats.bySession":`Session`,"features.hudEnable":`Mode HUD`,"features.hudEnableDesc":`Ajoute un bouton HUD à chaque session. Chrome / Edge : toujours au-dessus de vos autres applications ; autres navigateurs : une petite fenêtre.`,"features.hudFallback":`Ce navigateur ne sait pas garder une fenêtre au-dessus des autres applications : le HUD s’ouvre dans une petite fenêtre (Chrome ou Edge pour la barre toujours visible).`,"features.team":`Team`,"features.teamDesc":`Une entrée « Team » dans la barre latérale : des discussions avec des personnes qui ont leur propre harness-pilot (messages privés, groupes, sondages, fichiers), directement de serveur à serveur. Claude peut résumer les messages choisis, et chaque message peut être envoyé à une de vos sessions. Il faut une adresse https sur internet (mode domaine, pas Tailscale).`,"nset.device.testBody":`Les notifications fonctionnent dans ce navigateur.`,"nset.device.unsupported":`Ce navigateur n'a pas de notifications système : vous aurez le bandeau dans l'app et le son.`,"nset.hook.add":`Ajouter un webhook`,"nset.hook.addDesc":`Une URL privée à coller dans le service (Stripe, Shopify, GitHub ou tout outil qui envoie du JSON).`,"nset.hook.script":`script`,"nset.hook.notPublic":`Les webhooks demandent un serveur joignable depuis Internet en HTTPS (mode domaine). Sinon, publiez depuis un script sur le serveur : maxxing feed post.`,"nset.hook.cliHint":`Tout script peut aussi publier : maxxing feed post "Titre" --body "…" --level warning --source mail (voir Docs → Notifications).`,"nset.hook.test":`Envoyer un événement de test`,"nset.hook.testSent":`Événement de test envoyé`,"nset.hook.setSecret":`Ajouter le secret de signature`,"nset.hook.changeSecret":`Changer le secret de signature`,"nset.hook.regenerate":`Nouvelle URL`,"nset.hook.regenerateDesc":`L’URL actuelle ne marchera plus : collez la nouvelle dans le service.`,"nset.hook.delete":`Supprimer {name} ?`,"nset.hook.deleteDesc":`Son URL ne marchera plus. Ses événements passés restent dans le fil jusqu’à expiration.`,"nset.hook.secretTitle":`Secret de signature de {name}`,"nset.hook.secretPlaceholder":`Collez le secret de signature (facultatif)`,"nset.hook.secret":`Secret de signature`,"nset.hook.sourceName":`Nom`,"nset.hook.sourceNameHint":`Affiché dans le fil et utilisé pour sa règle Telegram.`,"nset.hook.create":`Créer`,"nset.hook.ready":`Webhook prêt`,"nset.hook.noSecretWarn":`Pas encore de secret de signature : les événements de ce service sont refusés tant que vous n’avez pas ajouté le secret qu’il fournit (menu … → Ajouter le secret de signature).`,"nset.hook.secretHelp.stripe":`Stripe → Développeurs → Webhooks → votre endpoint → Clé secrète de signature (whsec_…).`,"nset.hook.secretHelp.shopify":`Admin Shopify → Paramètres → Notifications → Webhooks : la clé affichée sous la liste.`,"nset.hook.secretHelp.github":`Le « Secret » que vous tapez en créant le webhook sur GitHub (un long texte aléatoire).`,"nset.hook.secretHelp.generic":`Facultatif. S’il est défini, l’expéditeur doit ajouter l’en-tête X-Signature: sha256=<HMAC-SHA256 du corps>.`,"nset.hook.where.stripe":`Dans Stripe : Développeurs → Webhooks → Ajouter un endpoint → collez cette URL, choisissez les événements (checkout.session.completed, charge.refunded, invoice.payment_failed…), puis copiez ici la clé de signature.`,"nset.hook.where.shopify":`Dans l’admin Shopify : Paramètres → Notifications → Webhooks → Créer un webhook (JSON, ex. Création de commande) → collez cette URL. Copiez la clé de signature affichée dans cette source.`,"nset.hook.where.github":`Sur GitHub : dépôt → Settings → Webhooks → Add webhook → collez cette URL, type application/json, le même secret qu’ici.`,"nset.hook.where.generic":`Envoyez du JSON en POST à cette URL : {"title": "…", "body": "…", "level": "info|success|warning|error", "url": "…", "id": "identifiant unique"}.`,"nset.hook.service":`Service`,"nset.hook.service.stripe":`Stripe (ventes, remboursements, paiements échoués)`,"nset.hook.service.shopify":`Shopify (commandes, remboursements, stock)`,"nset.hook.service.github":`GitHub (push, PR, workflows ratés, releases)`,"nset.hook.service.generic":`JSON générique (n’importe quel outil)`};export{e as default};